if(homeDefaultsPending)saved.preferences={...saved.preferences,homePerformanceVersion:1,sort:'return-desc',radarMode:'performance',radarRange:'1Y',radarSource:'market',radarDirection:'desc'};
const state={account:null,chain:0,session:0,provider:null,wallets:[],assets:[],prices:{},tokenChecks:{},balances:{},balanceComplete:false,eth:null,usdg:null,vaults:{},vaultErrors:{},status:null,artifact:null,loading:true,error:'',busy:false,nav:false,selected:'ai-chips',period:'1D',filter:'All baskets',search:'',sort:['name','assets','coverage','return-desc','return-asc'].includes(saved.preferences?.sort)?saved.preferences.sort:'return-desc',catalogueView:saved.preferences?.catalogueView==='grid'?'grid':'list',tokenSearch:'',tokenFilter:'all',portfolioTab:'positions',swap:{symbol:'NVDA',side:'buy',amount:'5',slippage:100},quote:null,quoteBusy:false,review:null,operation:'mint',shares:'1',creation:null,routeCheck:null,routeCheckBusy:false,radarMode:['composition','performance','buy'].includes(saved.preferences?.radarMode)?saved.preferences.radarMode:'performance',radarTheme:BASE_THEMES.some(t=>t.id===saved.preferences?.radarTheme)?saved.preferences.radarTheme:'ai-chips',radarRange:['OBSERVED','1D','1M','1Y'].includes(saved.preferences?.radarRange)?saved.preferences.radarRange:'1Y',radarSource:saved.preferences?.radarSource==='browser'?'browser':'market',radarDirection:saved.preferences?.radarDirection==='asc'?'asc':'desc',marketHistory:null,historyLoading:false,historyError:'',historyRetryAt:0,radarBudget:saved.preferences?.radarBudget||'5',radarEditing:false,radarError:''};
