const PUBLIC_RPC='https://rpc.mainnet.chain.robinhood.com';function createReader(url){const provider=new JsonRpcProvider(url,{chainId:CHAIN_ID,name:'Robinhood Chain'},{staticNetwork:true,batchMaxCount:10});provider.pollingInterval=3500;return provider;}let readSource=PUBLIC_RPC,read=createReader(readSource);function configureReader(status){const next=status.dedicatedRpc?location.origin+'/api/rpc':PUBLIC_RPC;if(next!==readSource){read.destroy();readSource=next;read=createReader(next);}}
