function routedVault(){const r=route();return r.startsWith('basket/')?r.slice(7):r.startsWith('fund/')?r.slice(5):r.startsWith('exit/')?r.slice(5):null;}
function route(){return location.hash.slice(1)||'discover';}function go(r){if(route()===r){render();window.scrollTo(0,0);}else location.hash=r;}
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function fail(e){const c=e?.code||e?.info?.error?.code;if(c===4001||c==='ACTION_REJECTED')return'You declined the wallet request. Nothing was submitted.';if(c==='INSUFFICIENT_FUNDS')return'Not enough ETH for the transaction and gas.';if(c==='CALL_EXCEPTION')return'Transaction simulation failed. Recheck balances, allowances and the latest basket amounts.';return String(e?.shortMessage||e?.message||e).slice(0,300);}
async function api(path,body){const r=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const d=await r.json();if(!r.ok)throw Error(d.error||'Service unavailable.');return d;}
function heading(t,p='',k=''){return`<div class="page-heading">${k?`<div class="eyebrow">${k}</div>`:''}<h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`;}
