function shell(body,standalone=false){return workspaceUI.shell(body);}

function p(symbol){return state.prices[symbol];}function priceLabel(symbol){return usd(p(symbol)?.ok?p(symbol).mid18:null);}
function sourceAge(symbol){const x=p(symbol);if(!x?.ok)return x?.error||'Awaiting source';if(x.spreadPct>5)return 'Wide spread '+x.spreadPct.toFixed(1)+'% · '+Math.max(0,Math.floor((Date.now()-Date.parse(x.at))/1000))+'s ago';return Math.max(0,Math.floor((Date.now()-Date.parse(x.at))/1000))+'s ago';}
