function recordObservation(key,value){if(value===null)return;const list=observations[key]||[];if(!list.length||Date.now()-list.at(-1).at>=60000)list.push({at:Date.now(),value:String(value)});observations[key]=retainObservations(list);try{localStorage.setItem(KEY+'-observations',JSON.stringify(observations));}catch{}}
