function composition(symbols,amounts,weights=[]){const value=completeValue(symbols,amounts,state.prices),current=currentWeights(symbols,amounts,state.prices);return`<div class="table-scroll"><table><thead><tr><th>ASSET</th><th>TOKENS / SHARE</th><th>CURRENT WEIGHT</th><th>REFERENCE MARK</th></tr></thead><tbody>${symbols.map((a,i)=>{const v=p(a)?.ok?BigInt(amounts[i])*p(a).mid18/SCALE:null;return`<tr><td><strong>${a}</strong><small>${weights[i]!==undefined?Number(weights[i])/100+'% initial':''}</small></td><td>${units(amounts[i],18,8)}</td><td>${current?current[i]/100+'%':'—'}</td><td>${priceLabel(a)}<small>${sourceAge(a)}</small></td></tr>`;}).join('')}</tbody></table></div>`;}
