function order(v){let q,amounts,error='';try{q=decimal(state.shares);if(q===0n)throw Error('Enter a positive share amount.');if(state.operation!=='mint'&&q>v.owned&&state.account)throw Error('Amount exceeds your share balance.');}catch(e){error=e.message;}amounts=v.orderAmounts||null;return`<section class="panel order-panel"><div class="flex-between"><h2>YOUR POSITION</h2>${badge('MAINNET')}</div><div class="vault-trade-links"><a class="btn primary wide" href="#fund/${v.address}">BUY BASKET WITH USDG</a><a class="btn wide" href="#exit/${v.address}">SELL BASKET FOR USDG</a></div><p class="footnote">One guided process: buy each component, approve deposits, then mint into this vault.</p>${v.supply===0n&&v.available.every(x=>x===0n)&&v.reserved.every(x=>x===0n)?`<div class="vault-unfunded"><h3>VAULT CREATED.<br>FUNDING IS NEXT.</h3><p>This vault currently holds no Stock Tokens. Deployment pays ETH gas and buys no stocks.</p><p>Use Buy basket with USDG above for a guided purchase, or deposit tokens you already hold below.</p><small>Purchases, approvals and minting need separate wallet confirmations.</small></div>`:''}<div class="wallet-row"><span>${state.account?short(state.account):'Connect your wallet'}</span>${btn(state.account?'REFRESH POSITION':'CONNECT WALLET',state.account?'refresh':'connect','outline')}</div><div class="meta-pair"><span>Your shares</span><strong>${state.account?units(v.owned)+' '+esc(v.symbol):'—'}</strong></div><div class="trade-tabs">${[['mint','Mint with tokens'],['redeem','Withdraw tokens'],['reserve','Reserve exit'],['claims','Claim']].map(([id,label])=>btn(label,'operation',state.operation===id?'active':'',`data-op="${id}"`)).join('')}</div>${state.operation==='claims'?exitList(v):`<label>SHARES<input id="live-shares" aria-label="Basket shares" type="number" min="0.000000001" step="any" value="${esc(state.shares)}"></label>${btn('CALCULATE EXACT TOKEN AMOUNTS','preview-operation','wide',`data-vault="${v.address}"`,!!error||!state.account||state.chain!==CHAIN_ID)}${error?`<div class="form-error">${esc(error)}</div>`:''}${amounts?`<div class="quote"><div class="meta-pair"><span>Reference value</span><strong>${usd(completeValue(v.symbols,amounts,state.prices))}</strong></div>${v.symbols.map((a,i)=>{const have=state.balances[a]||0n,need=BigInt(amounts[i]),missing=need>have?need-have:0n;return`<div class="component-need"><div class="meta-pair"><strong>${a}</strong><span>${units(need,18,8)}</span></div>${state.operation==='mint'?`<small>In wallet: ${units(have,18,8)}</small>${missing>0n?`${btn('Acquire '+units(missing,18,6)+' '+a,'acquire','text-btn',`data-symbol="${a}" data-amount="${missing}" data-vault="${v.address}"`)}<small>Needs a separate OpenOcean swap</small>`:btn('Review token approval','approve-vault','text-btn',`data-symbol="${a}" data-amount="${need}" data-vault="${v.address}"`)}`:''}</div>`;}).join('')}<small>These are token amounts, not a USD execution quote.</small></div><div class="notice small">${state.operation==='mint'?'Acquire missing components first, then approve exact token amounts and mint. These are separate transactions; partial component purchases remain in your wallet.':state.operation==='redeem'?'Burn shares and receive proportional underlying tokens. Selling those tokens for USDG is a separate operation.':'Burn shares and segregate proportional underlying tokens. A separate claim returns them to your wallet.'}</div>${btn('REVIEW '+({mint:'MINT',redeem:'WITHDRAWAL',reserve:'RESERVE'})[state.operation],'review-vault-op','primary wide',`data-vault="${v.address}"`)}<div id="operation-error" class="form-error" role="alert"></div>`:'<p class="footnote">Calculate a fresh onchain preview before reviewing a transaction.</p>'}`}</section>`;}
function exitList(v){const exits=v.exits||[];return exits.filter(e=>!e.claimed).map(e=>`<div class="claim-row"><div><strong>Reserve #${e.id}</strong><small>${units(e.shares)} shares burned</small><small>${v.symbols.map((s,i)=>units(e.amounts[i],18,8)+' '+s).join(' + ')}</small></div>${btn('Review claim','review-claim','',`data-vault="${v.address}" data-exit="${e.id}"`)}</div>`).join('')||'<p class="small muted">No unclaimed reserves for this wallet.</p>';}
function vaultPage(a){const v=state.vaults[a.toLowerCase()];if(!v)return`${heading('READING THE VAULT.','Runtime, composition and backing must pass checks before operations appear.')}<div class="notice ${state.vaultErrors[a.toLowerCase()]?'warn':''}">${esc(state.vaultErrors[a.toLowerCase()]||'Fetching chain state…')}</div>${importPanel()}`;const q=v.supply>0n?v.available.map(x=>x*SCALE/v.supply):v.initial,value=completeValue(v.symbols,q,state.prices);return`${heading(esc(v.name),esc(v.thesis),'ONCHAIN / FIXED COMPOSITION')}<div class="basket-meta">${badge('VERIFIED RUNTIME','lime')}<a class="address" target="_blank" rel="noreferrer" href="https://robinhoodchain.blockscout.com/address/${v.address}">${short(v.address)}</a><span>Creator ${short(v.creator)}</span>${btn('Copy link','copy','text-btn',`data-address="${v.address}"`)}</div><div class="community-grid basket-detail"><div><section class="panel"><div class="flex-between"><h2>${v.supply===0n?'PLANNED SHARE VALUE':'OBSERVED SHARE VALUE'}</h2>${periods()}</div><div class="chart-heading"><strong>${usd(value)} <em>/ share estimate</em></strong></div>${chart(v.address)}<p class="footnote">${v.supply===0n?'Planned funding target only. No basket shares are outstanding.':'Only real observations collected by this browser. Not an executable sale quote.'}</p></section><section class="panel"><h2>${v.supply===0n?'PLANNED TOKENS PER SHARE':'WHAT BACKS YOUR SHARE'}</h2>${composition(v.symbols,q,v.weights)}${v.supply===0n?'<p class="footnote">Funding targets per new share. Actual active and reserved balances are listed below.</p>':''}</section><section class="panel"><h2>PROOF OF BACKING</h2><div class="meta-pair"><span>Outstanding shares</span><strong>${units(v.supply)}</strong></div><div class="meta-pair"><span>Maximum supply</span><strong>${units(v.max)}</strong></div><div class="table-scroll"><table><thead><tr><th>TOKEN</th><th>ACTIVE BACKING</th><th>RESERVED / EXCLUDED</th></tr></thead><tbody>${v.symbols.map((s,i)=>`<tr><td>${s}</td><td>${units(v.available[i],18,8)}</td><td>${units(v.reserved[i],18,8)}</td></tr>`).join('')}</tbody></table></div><p class="footnote">Read at RH block ${v.block}. No curator withdrawal or composition-change functions exist in this runtime.</p></section></div><div>${order(v)}<section class="panel quiet"><h3>SELL THE WHOLE SET</h3><p>Redeem your shares and sell all received components for USDG in one guided process, with separate wallet confirmations.</p><a class="btn primary wide" href="#exit/${v.address}">SELL BASKET FOR USDG</a></section></div></div>`;}
