function lastSwapPanel(){const f=saved.lastSwap;if(!f||f.account!==state.account)return '';const buy=f.side==='buy';return `<section class="quote"><h3>CONFIRMED ONCHAIN</h3><div class="meta-pair"><span>Actually spent</span><strong>${units(BigInt(f.sellAmount),buy?6:18,12)} ${buy?'USDG':f.symbol}</strong></div><div class="meta-pair"><span>Actually received</span><strong>${units(BigInt(f.buyAmount),buy?18:6,12)} ${buy?f.symbol:'USDG'}</strong></div><a class="address" href="https://robinhoodchain.blockscout.com/tx/${f.hash}" target="_blank" rel="noreferrer">RH block ${f.block} / ${short(f.hash)}</a><p class="footnote">Verified from this transaction's token Transfer events.</p>${buy?btn('REVIEW SALE OF THIS PURCHASE','sell-purchase','wide'):''}</section>`;}
function quotePanel(){const q=state.quote,buy=state.swap.side==='buy';return `<div class="quote active-swap-quote"><div class="meta-pair"><span>Exact spend</span><strong>${units(BigInt(q.spendingCap),buy?6:18,12)} ${buy?'USDG':state.swap.symbol}</strong></div><div class="meta-pair"><span>Minimum received</span><strong>${units(BigInt(q.minBuyAmount),buy?18:6,12)} ${buy?state.swap.symbol:'USDG'}</strong></div><div class="meta-pair"><span>Provider price impact</span><strong>${esc(q.priceImpact)}</strong></div><div class="meta-pair"><span>Approval spender</span><strong>${short(q.approvalSpender)}</strong></div><p class="footnote">Expires ${new Date(q.expiresAt).toLocaleTimeString()}. Refresh after an approval is included. Gas is extra. ${state.swap.targetAmount&&BigInt(q.minBuyAmount)<BigInt(state.swap.targetAmount)?'Minimum output is below the basket target; increase your USDG budget if you need the full component quantity.':''}</p>${btn('REVIEW EXACT APPROVAL','approve-swap','wide')}${btn('REVIEW SWAP','review-swap','primary wide')}</div>`;}
