function missing(){return`${heading('SET NOT FOUND.','Open a real vault address, or create a new basket.')}<a class="btn primary" href="#onchain">OPEN A VAULT</a>`;}
function render(){const r=route();const titles={radar:'Basket Radar',discover:'Discover',portfolio:'My portfolio',onchain:'Onchain baskets',community:'Create a basket',tokens:'Token universe',data:'Data & network',methodology:'Methodology',watchlist:'Watchlist',sectors:'Sector coverage'};document.title=(r.startsWith('fund/')?'Buy basket':r.startsWith('exit/')?'Sell basket':titles[r]||'Basket')+' | HOODSET';let body;if(r.startsWith('exit/'))body=isAddress(r.slice(5))?(atomic.enabled()?atomic.page(r.slice(5),'sell'):atomic.modeTabs()+liquidation.page(r.slice(5))):missing();else if(r.startsWith('fund/'))body=isAddress(r.slice(5))?(atomic.enabled()?atomic.page(r.slice(5),'buy'):atomic.modeTabs()+funding.page(r.slice(5))):missing();else if(r.startsWith('basket/'))body=isAddress(r.slice(7))?vaultPage(r.slice(7).toLowerCase()):`${heading('CHECK THIS BASKET LINK.','A live basket needs a valid RH vault address. Paper basket links open in the separate sandbox.')}<a class="btn" href="/paper.html#${esc(r)}">Open paper archive</a>`;else if(r.startsWith('theme/'))body=themePage(r.slice(6));else body=({radar:workspaceUI.radarPage,discover,portfolio:portfolioPage,onchain,community:builder,tokens:tokensPage,data:dataPage,methodology,watchlist:workspaceUI.watchlist,sectors:workspaceUI.sectors})[r]?.()||missing();$('#app').innerHTML=shell(body);alignRadarList();}
function alignRadarList(){const list=$('.radar-list'),active=list?.querySelector('button.active');if(list&&active&&innerWidth<=680)list.scrollLeft+=active.getBoundingClientRect().left-list.getBoundingClientRect().left;}
addEventListener('resize',alignRadarList,{passive:true});

function expirePrices(){let changed=false;for(const x of Object.values(state.prices))if(x.ok&&Date.now()-Date.parse(x.at)>120000){x.ok=false;x.error='Stale price';changed=true;}return changed;}
async function refresh(){if(state.loading)return;state.loading=true;state.error='';render();try{const[status,registry,data]=await Promise.all([api('status'),api('assets'),api('prices')]);configureReader(status);state.status=status;state.assets=registry.assets;const chain=Number(BigInt(await read.send('eth_chainId',[])));if(chain!==CHAIN_ID)throw Error('Read RPC returned the wrong chain. Operations disabled.');state.status=status;state.assets=registry.assets;const checks={};await Promise.all(Object.keys(ALLOWED).map(async s=>{try{const t=token(s),[paused,multiplier,decimals]=await Promise.all([t.oraclePaused(),t.uiMultiplier(),t.decimals()]);checks[s]={paused,multiplier,decimals:Number(decimals)};}catch(e){checks[s]={error:'Onchain token checks unavailable'};}}));state.tokenChecks=checks;state.prices={};for(const s of Object.keys(ALLOWED)){const asset=state.assets.find(a=>a.tokenSymbol===s),row=data.prices.find(p=>p.symbol===s);state.prices[s]=asset?adjustedPrice(asset,row?.quote,checks[s]):{ok:false,error:'Asset is not currently active'};}if(state.account){await loadBalances();await funding.reconcile();await liquidation.reconcile();const recoveryErrors=await reconcileActivity(saved.activity,state.account,hash=>read.getTransactionReceipt(hash),recoverReceipt);save();if(recoveryErrors.length)state.error='Some included transactions need another receipt check. Open portfolio Activity and refresh.';}const addresses=[...new Set([...(Array.isArray(saved.vaults)?saved.vaults:[]),...(routedVault()&&isAddress(routedVault())?[routedVault().toLowerCase()]:[])])].slice(0,50);await Promise.all(addresses.map(a=>loadVault(a)));}catch(e){state.error=fail(e);}state.loading=false;expirePrices();render();}
async function loadBalances(){if(!state.account)return;state.balanceComplete=false;const account=state.account,session=state.session;const[eth,usdg,decimals,balances]=await Promise.all([read.getBalance(account),token('USDG').balanceOf(account),token('USDG').decimals(),Promise.all(Object.keys(ALLOWED).map(async a=>{try{return[a,await token(a).balanceOf(account)];}catch{return[a,null];}}))]);if(Number(decimals)!==6)throw Error('USDG decimals differ from the verified integration.');if(session!==state.session)return;state.eth=eth;state.usdg=usdg;state.balances=Object.fromEntries(balances.filter(([,v])=>v!==null));if(balances.some(([,v])=>v===null))throw Error('Some token balances could not be read. The portfolio is incomplete.');state.balanceComplete=true;}
async function loadVault(address){const a=address.toLowerCase();if(!isAddress(a))throw Error('Enter a valid vault address.');const session=state.session,account=state.account;try{const code=await read.getCode(a);if(code==='0x'||keccak256(code)!==state.artifact.runtimeHash)throw Error('This address does not match the compiled HOODSET vault runtime.');const v=vault(a),[name,symbol,thesis,creator,supply,max,assets,initial,weights,available,block]=await Promise.all([v.name(),v.symbol(),v.thesis(),v.creator(),v.totalSupply(),v.maxSupply(),v.assets(),v.initialQuantities(),v.initialWeights(),v.availableBalances(),read.getBlockNumber()]);const symbols=assets.map(a=>Object.keys(ALLOWED).find(s=>ALLOWED[s].toLowerCase()===a.toLowerCase()));if(assets.length<2||assets.length>12||symbols.some(s=>!s)||new Set(symbols).size!==symbols.length)throw Error('Composition contains an unsupported asset.');const reserved=await Promise.all(assets.map((_,i)=>v.reserved(i)));const owned=account?await v.balanceOf(account):0n;const exits=[];if(account){const count=Number(await v.exitCount(account));if(count>500)throw Error('Too many exits for the browser reader; use an indexer.');for(let i=0;i<count;i++){const id=await v.exitIdAt(account,i),e=await v.exitInfo(id);exits.push({id,owner:e.owner,claimed:e.claimed,shares:e.shares,amounts:[...e.amounts]});}}
if(session!==state.session)throw Error('Wallet changed while reading this vault. Refresh again.');state.vaults[a]={address:a,name,symbol,thesis,creator,supply,max,assets:[...assets],symbols,initial:[...initial],weights:[...weights],available:[...available],reserved,owned,exits,block};delete state.vaultErrors[a];const perShare=supply>0n?available.map(x=>x*SCALE/supply):[...initial];if(supply>0n)recordObservation(a,completeValue(symbols,perShare,state.prices));return state.vaults[a];}catch(e){delete state.vaults[a];state.vaultErrors[a]=fail(e);throw e;}}
function modal(title,body){$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="flex-between"><h2>${title}</h2>${btn(icon('close'),'close','icon-btn','aria-label="Close dialog"')}</div>${body}</section></div>`;document.body.classList.add('modal-open');$('#overlay button')?.focus();}
function close(){if(state.busy)return;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');state.review=null;}
function connectDialog(){if(state.account){modal('YOUR WALLET',`<p>${esc(state.account)}</p><div class="meta-pair"><span>Network chain ID</span><strong>${state.chain}</strong></div><div class="button-row">${btn('Refresh balances','refresh')}${btn('Disconnect from site','disconnect')}</div>`);return;}const options=state.wallets.map((w,i)=>btn(esc(w.info.name),'choose-wallet','wide',`data-index="${i}"`)).join('');modal('CONNECT YOUR WALLET',`<p>Read your real RH balances and prepare transactions. Every write requires a separate wallet confirmation.</p>${options||'<div class="notice">No browser wallet detected. Open this site in Chrome with Rabby, MetaMask or another EIP-1193 wallet. The in-app browser may not expose wallet extensions.</div>'}${!options?btn('COPY SITE LINK','copy-site','wide'):''}<p class="footnote">${route().startsWith('exit/')?'Selling needs basket shares and ETH for gas on RH mainnet. USDG is the output.':'You need ETH for gas and USDG for purchases on RH mainnet.'} <a href="#data">Check connections</a>. Never enter a seed phrase or private key here.</p>`);}
let detachWallet=()=>{};
let restoringWallet=false;
function clearWallet(){detachWallet();detachWallet=()=>{};state.session++;state.account=null;state.provider=null;state.chain=0;state.eth=null;state.usdg=null;state.balances={};state.balanceComplete=false;state.vaults={};state.quote=null;state.review=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');}
async function connect(i,restore=false){const w=state.wallets[i];if(!w)throw Error('Wallet is no longer available.');const session=await walletSession(w.provider,!restore);if(!session)return;clearWallet();state.provider=w.provider;state.account=session.account;state.chain=session.chain;saved.wallet={id:walletId(w.info),name:w.info.name};save();
const changed=async()=>{try{const current=await walletSession(w.provider);if(state.provider!==w.provider)return;if(!current){clearWallet();delete saved.wallet;save();render();return;}state.session++;state.account=current.account;state.chain=current.chain;state.quote=null;state.review=null;state.eth=null;state.usdg=null;state.balances={};state.balanceComplete=false;state.vaults={};$('#overlay').innerHTML='';document.body.classList.remove('modal-open');await refresh();}catch(e){state.error=fail(e);render();}};
detachWallet=observeWallet(w.provider,changed,changed,()=>{clearWallet();delete saved.wallet;save();render();});close();await refresh();}
async function restoreWallet(){if(restoringWallet||state.provider||!saved.wallet)return;const i=state.wallets.findIndex(w=>walletId(w.info)===saved.wallet.id);if(i<0)return;restoringWallet=true;try{await connect(i,true);}catch(e){notify('Reconnect your wallet: '+fail(e));}finally{restoringWallet=false;}}
async function assertWallet(expected){if(!state.provider||!state.account)throw Error('Connect a browser wallet first.');const[accounts,chain,rpcChain]=await Promise.all([state.provider.request({method:'eth_accounts'}),state.provider.request({method:'eth_chainId'}),read.send('eth_chainId',[])]);if(Number(BigInt(rpcChain))!==CHAIN_ID)throw Error('The read RPC is not on RH mainnet. Operations disabled.');if(Number(BigInt(chain))!==CHAIN_ID)throw Error('Switch the wallet to Robinhood Chain 4663.');if(accounts?.[0]?.toLowerCase()!==state.account||expected&&expected!==state.account)throw Error('Wallet account changed. Review again.');return state.account;}
async function switchNetwork(){if(!state.provider)throw Error('Connect a wallet first.');try{await state.provider.request({method:'wallet_switchEthereumChain',params:[{chainId:'0x1237'}]});}catch(e){if(e.code!==4902)throw e;await state.provider.request({method:'wallet_addEthereumChain',params:[{chainId:'0x1237',chainName:'Robinhood Chain',nativeCurrency:{name:'Ether',symbol:'ETH',decimals:18},rpcUrls:['https://rpc.mainnet.chain.robinhood.com'],blockExplorerUrls:['https://robinhoodchain.blockscout.com']}]});}state.chain=Number(BigInt(await state.provider.request({method:'eth_chainId'})));render();}
async function transactionReview(label,tx,details,onIncluded,expiresAt=Date.now()+90000,recovery=null){const account=await assertWallet();if(state.review)throw Error('Close the current review first.');const operationKey=transactionKey(tx);await checkPending(saved.activity,account,operationKey,hash=>read.getTransactionReceipt(hash));save();const request={...tx,from:account,chainId:CHAIN_ID};await read.call(request);const[gas,fee]=await Promise.all([read.estimateGas(request),read.getFeeData()]);const gasLimit=gas*120n/100n,estimate=gasLimit*(fee.maxFeePerGas||fee.gasPrice||0n);const eth=await read.getBalance(account);if(eth<BigInt(tx.value||0n)+estimate)throw Error('Not enough ETH for the transaction and estimated gas. Fund your RH wallet first.');state.review={recovery:recovery||(!tx.to?{kind:'deploy'}:null),label,operationKey,tx:{...request,gasLimit},account,session:state.session,expiresAt,onIncluded};modal(label,`${details}<div class="meta-pair"><span>Chain / account</span><strong>4663 / ${short(account)}</strong></div><div class="meta-pair"><span>Target</span><strong>${tx.to?short(tx.to):'New HOODSET vault'}</strong></div><div class="meta-pair"><span>ETH value</span><strong>${units(tx.value||0n,18,8)} ETH</strong></div><div class="meta-pair"><span>Estimated gas cost</span><strong>${units(estimate,18,8)} ETH</strong></div><p class="footnote">The wallet shows final fees. This review expires at ${new Date(expiresAt).toLocaleTimeString()}.</p><div class="notice small">This is a real mainnet transaction. No transaction has been sent yet. Review the target, token amounts and wallet details before signing.</div><div id="send-error" role="alert" class="form-error"></div>${btn('CONTINUE IN WALLET','send','primary wide')}`);}
async function send(){
 if(state.busy)return;const r=state.review;if(!r)return;
 if(r.sentHash)throw Error('Already submitted: '+r.sentHash+'. Check the explorer before retrying.');
 state.busy=true;let requested=false,intentStarted=false;
 const button=$('button[data-action="send"]');
 try{
  await assertWallet(r.account);if(state.session!==r.session||Date.now()>r.expiresAt)throw Error('This review expired or the account changed. Close it and review again.');
  if(button){button.disabled=true;button.textContent='VERIFYING TRANSACTION';}
  if(r.recovery?.kind?.startsWith('atomic.')||r.recovery?.kind?.startsWith('funding.')||r.recovery?.kind?.startsWith('liquidation.'))await checkWalletQueue(saved.activity,[...(Array.isArray(saved.fundingRuns)?saved.fundingRuns:[]),...(Array.isArray(saved.liquidationRuns)?saved.liquidationRuns:[]),...atomic.queue()],r.account,r.recovery.fund||r.recovery.exit,hash=>read.getTransactionReceipt(hash));
  await funding.beforeSend(r);await liquidation.beforeSend(r);await atomic.beforeSend(r);await assertWallet(r.account);
  if(state.session!==r.session||Date.now()>r.expiresAt)throw Error('This review expired. Close it and continue for a fresh review.');
  await read.call(r.tx);
  const wallet=new BrowserProvider(state.provider),signer=await wallet.getSigner();
  intentStarted=true;funding.sending(r);liquidation.sending(r);atomic.sending(r);requested=true;
  if(button)button.textContent='AWAITING WALLET CONFIRMATION';
  const tx=await signer.sendTransaction(r.tx);r.sentHash=tx.hash;
  const row={label:r.label,operationKey:r.operationKey,hash:tx.hash,account:r.account,at:Date.now(),status:'Submitted',target:r.tx.to||null,nonce:tx.nonce,recovery:r.recovery};
  saved.activity.unshift(row);saved.activity=saved.activity.slice(0,100);save();funding.submitted(row);liquidation.submitted(row);atomic.submitted(row);
  if(button)button.textContent='WAITING FOR RH INCLUSION';
  const receipt=await read.waitForTransaction(tx.hash,1,180000);
  if(!receipt)throw Error('Still pending. Check the explorer before retrying.');
  row.status=receipt.status===1?'Included in RH block':'Reverted';save();
  if(receipt.status!==1)throw Error('The transaction reverted. Close this review and refresh receipts before continuing.');
  state.busy=false;state.review=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');state.quote=null;
  await recoverReceipt(row,receipt);await r.onIncluded?.(receipt);row.recoveryComplete=true;save();
  const settlementError=state.error;await refresh();if(settlementError){state.error=settlementError;render();}
  notify(r.label+' included in RH block '+receipt.blockNumber+'.');
 }catch(e){state.busy=false;funding.rejected(r,e,requested,intentStarted);liquidation.rejected(r,e,requested,intentStarted);atomic.rejected(r,e,requested,intentStarted);throw e;}
}
function syncDraft(){const f=$('#live-builder');if(!f)return;draft.name=f.elements.name.value;draft.symbol=f.elements.symbol.value.toUpperCase().replace(/[^A-Z0-9]/g,'');f.elements.symbol.value=draft.symbol;draft.thesis=f.elements.thesis.value;draft.maxSupply=f.elements.maxSupply.value;save();}
async function deployReview(){syncDraft();const account=await assertWallet();const copy=structuredClone(draft);await refresh();const bytes=s=>new TextEncoder().encode(s).length;if(!copy.name.trim()||bytes(copy.name)>48||!copy.thesis.trim()||bytes(copy.thesis)>280||!/^[A-Z][A-Z0-9]{1,7}$/.test(copy.symbol))throw Error('Enter a name (48 bytes max), symbol (2–8 uppercase letters/numbers), and thesis (280 bytes max).');if(!/^[1-9]\d{0,6}$/.test(copy.maxSupply)||BigInt(copy.maxSupply)>1000000n)throw Error('Maximum supply must be 1–1,000,000 whole shares.');const{amounts,weights}=initialAmounts(copy.assets,state.prices);for(const a of copy.assets)if(!state.assets.some(x=>x.tokenSymbol===a.symbol))throw Error(a.symbol+' is not active in the official registry.');const plannedShares=copy.budgetUSDG?budgetPlan({assets:copy.assets.map(a=>a.symbol),weights:copy.assets.map(a=>a.weight)},copy.budgetUSDG,state.prices).shares18:null;if(plannedShares!==null&&plannedShares>parseUnits(copy.maxSupply,18))throw Error('The planned mint exceeds maximum shares. Increase the cap or revise the budget.');const args=[copy.name.trim(),copy.symbol,copy.thesis.trim(),copy.assets.map(a=>ALLOWED[a.symbol]),amounts,weights,parseUnits(copy.maxSupply,18)];const f=new ContractFactory(state.artifact.abi,state.artifact.bytecode);const tx=await f.getDeployTransaction(...args);await transactionReview('DEPLOY '+esc(copy.symbol)+' VAULT',tx,`<h3>${esc(copy.name)}</h3><p>${esc(copy.thesis)}</p>${composition(copy.assets.map(a=>a.symbol),amounts,weights)}<div class="meta-pair"><span>Maximum shares</span><strong>${copy.maxSupply}</strong></div><div class="notice warn small">New, unaudited contract. This transaction deploys the vault and spends gas; it does not buy or deposit components.</div><div class="source-links"><a href="/chain/HoodsetVault.sol" target="_blank">Review source</a><a href="/chain/standard-input.json" target="_blank">Compiler input</a></div>`,async receipt=>{if(!receipt.contractAddress)throw Error('Deployment receipt has no contract address.');const address=receipt.contractAddress.toLowerCase();await loadVault(address);saved.vaults=[...new Set([...(saved.vaults||[]),address])];save();if(copy.budgetUSDG){state.shares=formatUnits(plannedShares,18);state.operation='mint';}go('basket/'+address);},Date.now()+90000);}
async function previewOperation(address){const account=await assertWallet(),a=address.toLowerCase();await loadVault(a);const v=state.vaults[a],shares=decimal(state.shares);if(shares<=0n)throw Error('Enter a positive amount.');if(state.operation!=='mint'&&shares>v.owned)throw Error('Amount exceeds your available shares.');const amounts=state.operation==='mint'?await vault(a).previewMint(shares):await vault(a).previewRedeem(shares);v.orderAmounts=[...amounts];v.orderShares=shares;v.orderOperation=state.operation;v.orderSession=state.session;v.orderAccount=account;v.previewAt=Date.now();if(state.operation==='mint'){saved.journey={account,vault:a,shares:state.shares};save();}render();}
async function approveToken(symbol,spender,amount,recovery=null){await assertWallet();if(recovery?.kind?.startsWith('atomic.'))await atomic.verifyRouter(spender);else{if(!isAddress(spender)||spender.toLowerCase()!==OPENOCEAN_ROUTER.toLowerCase()&&!state.vaults[spender.toLowerCase()])throw Error('Approval target has not been verified.');if(spender.toLowerCase()!==OPENOCEAN_ROUTER.toLowerCase())await loadVault(spender);}const t=token(symbol),current=await t.allowance(state.account,spender),needed=BigInt(amount);if(needed<=0n)throw Error('Approval amount must be positive.');if(current>=needed){notify('Existing allowance already covers this exact amount.');return;}const reset=current>0n;const value=reset?0n:needed;const tx={to:symbol==='USDG'?USDG:ALLOWED[symbol],data:t.interface.encodeFunctionData('approve',[spender,value]),value:0n};await transactionReview(reset?'RESET TOKEN APPROVAL':'APPROVE '+symbol,tx,`<div class="meta-pair"><span>Token</span><strong>${symbol}</strong></div><div class="meta-pair"><span>Exact approval</span><strong>${units(value,symbol==='USDG'?6:18,12)}</strong></div><div class="meta-pair"><span>Spender</span><strong>${esc(spender)}</strong></div><p class="small">${reset?'Reset the existing allowance first, then approve the requested amount in a new transaction.':'No unlimited approval is requested. An approval permits token spending; it does not itself mint shares or execute a swap.'}</p>`,async()=>{state.quote=null;notify('Approval included. Continue for a fresh quote or mint preview.');},Date.now()+90000,recovery?{...recovery,symbol,spender,amount:String(value)}:null);}
async function reviewOperation(address){const a=address.toLowerCase(),v=state.vaults[a];await assertWallet();if(!v?.orderAmounts||v.orderSession!==state.session||v.orderAccount!==state.account||Date.now()-v.previewAt>90000||v.orderShares!==decimal(state.shares)||v.orderOperation!==state.operation)throw Error('Calculate a new onchain preview first.');const q=v.orderShares,amounts=[...v.orderAmounts],op=state.operation;if(op==='mint'){expirePrices();if(v.symbols.some(s=>!p(s)?.ok))throw Error('All components need fresh prices for the mint review. Refresh the market.');await loadBalances();for(let i=0;i<v.assets.length;i++){if((state.balances[v.symbols[i]]||0n)<amounts[i])throw Error('Acquire the missing '+v.symbols[i]+' first.');if(await token(v.symbols[i]).allowance(state.account,a)<amounts[i])throw Error('Approve the required '+v.symbols[i]+' amount first.');}}
const fn=op==='mint'?'mintShares':op==='redeem'?'redeem':'reserveExit',args=op==='reserve'?[q,amounts]:[q,state.account,amounts];const tx={to:a,data:vault(a).interface.encodeFunctionData(fn,args),value:0n};await transactionReview(({mint:'MINT SHARES',redeem:'WITHDRAW UNDERLYING',reserve:'RESERVE EXIT'})[op],tx,`<p>${esc(v.name)} / ${units(q)} ${esc(v.symbol)}</p>${v.symbols.map((s,i)=>`<div class="meta-pair"><span>${s}</span><strong>${units(amounts[i],18,12)} tokens</strong></div>`).join('')}<p class="small">${op==='mint'?'The contract pulls exact component amounts from your wallet and issues shares. Quote bounds protect against changed backing.':op==='redeem'?'Shares are burned and underlying tokens are sent to your connected wallet.':'Shares are burned and tokens become a separate, wallet-owned reserve. Claim them in a separate transaction.'}</p>`,async()=>{await loadVault(a);if(op==='mint'&&saved.journey?.vault===a){delete saved.journey;save();}});}
async function reviewClaim(address,id){const a=address.toLowerCase();await assertWallet();const v=await loadVault(a),e=v.exits.find(e=>e.id===BigInt(id));if(!e||e.claimed||e.owner.toLowerCase()!==state.account)throw Error('This reserve is not claimable by your wallet.');const tx={to:a,data:vault(a).interface.encodeFunctionData('claim',[e.id,state.account]),value:0n};await transactionReview('CLAIM RESERVED TOKENS',tx,`<p>Reserve #${e.id} / ${esc(v.name)}</p>${v.symbols.map((s,i)=>`<div class="meta-pair"><span>${s}</span><strong>${units(e.amounts[i],18,12)} tokens</strong></div>`).join('')}`,async()=>loadVault(a));}
async function getQuote(){if(state.quoteBusy)return;state.quoteBusy=true;state.quote=null;render();try{await assertWallet();expirePrices();const symbol=state.swap.symbol;if(!p(symbol)?.ok)throw Error(symbol+' needs a fresh, non-paused reference mark. Refresh the market.');const amount=decimal(state.swap.amount,state.swap.side==='buy'?6:18);if(amount<=0n)throw Error('Enter a positive token amount.');const balance=await token(state.swap.side==='buy'?'USDG':symbol).balanceOf(state.account);if(balance<amount)throw Error('Not enough '+(state.swap.side==='buy'?'USDG':symbol)+' for this exact spend.');const fingerprint=JSON.stringify(state.swap),session=state.session,input={symbol,side:state.swap.side,amount:String(amount),slippageBps:state.swap.slippage,taker:state.account};const quote=await fetchOpenOcean(openOceanInput(input),browserOpenOceanJson);if(session!==state.session||fingerprint!==JSON.stringify(state.swap))throw Error('Wallet or trade parameters changed. Request a fresh quote.');reviewOpenOcean(quote,input);state.quote=quote;state.quoteSession=session;state.quoteInput=fingerprint;}catch(e){state.quote=null;throw e;}finally{state.quoteBusy=false;render();}}
function validQuote(){if(state.quoteSession!==state.session||state.quoteInput!==JSON.stringify(state.swap))throw Error('Request a fresh quote for this wallet and amount.');return reviewOpenOcean(state.quote,{symbol:state.swap.symbol,side:state.swap.side,amount:String(decimal(state.swap.amount,state.swap.side==='buy'?6:18)),slippageBps:state.swap.slippage,taker:state.account});}
async function reviewSwap(){const account=await assertWallet(),q=validQuote();expirePrices();if(!p(state.swap.symbol)?.ok||state.tokenChecks[state.swap.symbol]?.paused)throw Error('Reference price is no longer valid. Refresh and quote again.');const sellSymbol=q.side==='buy'?'USDG':q.symbol,buySymbol=q.side==='buy'?q.symbol:'USDG',amount=BigInt(q.spendingCap),balance=await token(sellSymbol).balanceOf(account),allowance=await token(sellSymbol).allowance(account,OPENOCEAN_ROUTER);if(balance<amount)throw Error('Not enough '+sellSymbol+' for this exact spend.');if(allowance<amount)throw Error('Approve the exact amount first, then request a fresh quote.');for(const address of[OPENOCEAN_ROUTER,OPENOCEAN_CALLER])if(await read.getCode(address)==='0x')throw Error('Verified swap infrastructure is unavailable on this chain.');const tx={to:q.transaction.to,data:q.transaction.data,value:0n};await transactionReview('SWAP '+sellSymbol+' / '+buySymbol,tx,`<div class="meta-pair"><span>Exact spend</span><strong>${units(amount,q.side==='buy'?6:18,12)} ${sellSymbol}</strong></div><div class="meta-pair"><span>Minimum receipt</span><strong>${units(BigInt(q.minBuyAmount),q.side==='buy'?18:6,12)} ${buySymbol}</strong></div><div class="meta-pair"><span>Recipient</span><strong>${esc(account)}</strong></div><p class="small">OpenOcean / RH 4663. Public provider fees up to 0.5% by category, plus gas and underlying pool costs. The minimum receipt includes provider deductions and slippage. This swap changes your component token balances; basket shares are minted separately.</p>`,async receipt=>{state.quote=null;saved.lastSwap=null;try{saved.lastSwap=swapSettlement(receipt,q);const row=saved.activity.find(x=>x.hash===receipt.hash);if(row)row.trade=saved.lastSwap;save();}catch(e){state.error=fail(e);notify(state.error);}await loadBalances();},q.expiresAt,{kind:'swap',quote:q});}
function inputError(e){const target=$('#send-error')||$('#exit-error')||$('#fund-error')||$('#operation-error')||$('#swap-error')||$('#builder-error')||$('#import-error');if(target)target.textContent=fail(e);else notify(fail(e));}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;if(state.busy)return;const a=el.dataset.action;try{if(a.startsWith('atomic-')){await atomic.action(a,el);return;}if(a.startsWith('exit-')){await liquidation.action(a,el);return;}if(a.startsWith('fund-')){await funding.action(a,el);return;}if(a.startsWith('radar-')){handleRadarAction(a,el);return;}if(a==='skip-content'){$('#workspace-content')?.focus();return;}if(a==='search'){if(state.nav){state.nav=false;render();}openSearch();return;}if(a==='open-route'){close();go(el.dataset.route);return;}if(a==='select-theme'){state.selected=el.dataset.id;render();return;}if(a==='catalogue-view'){state.catalogueView=el.dataset.view==='grid'?'grid':'list';saved.preferences={...saved.preferences,catalogueView:state.catalogueView};save();render();return;}if(a==='clear-catalogue'){state.search='';state.filter='All baskets';render();return;}if(a==='clear-tokens'){state.tokenSearch='';state.tokenFilter='all';render();return;}if(a==='portfolio-tab'){state.portfolioTab=el.dataset.tab;render();return;}if(a==='close'){close();return;}if(a==='menu'){state.nav=!state.nav;render();return;}if(a==='refresh'){close();await refresh();return;}if(a==='connect'){connectDialog();return;}if(a==='copy-site'){await navigator.clipboard.writeText(location.origin+'/#'+(route().startsWith('fund/')||route().startsWith('exit/')?route():'tokens'));notify('Site link copied. Open it in your wallet browser.');return;}if(a==='check-routes'){await checkRoutes();return;}if(a==='resume-basket'){const j=saved.journey;if(!j||j.account!==state.account||!isAddress(j.vault))throw Error('Connect the wallet that started funding this basket.');state.operation='mint';state.shares=j.shares;go('basket/'+j.vault);await loadBalances();await previewOperation(j.vault);return;}if(a==='clear-journey'){delete saved.journey;save();render();return;}if(a==='sell-token'){const amount=state.balances[el.dataset.symbol];if(!amount||amount<=0n)throw Error('No available token balance.');state.swap={symbol:el.dataset.symbol,side:'sell',amount:formatUnits(amount,18),slippage:100};state.quote=null;go('tokens');return;}if(a==='choose-wallet'){await connect(Number(el.dataset.index));return;}if(a==='disconnect'){clearWallet();delete saved.wallet;save();await refresh();return;}if(a==='switch'){await switchNetwork();return;}if(a==='watch'){saved.watch=saved.watch.includes(el.dataset.id)?saved.watch.filter(x=>x!==el.dataset.id):[...saved.watch,el.dataset.id];save();render();return;}if(a==='filter'){state.filter=el.dataset.filter;render();return;}if(a==='period'){state.period=el.dataset.period;render();return;}if(a==='template'){syncDraft();delete draft.budgetUSDG;const t=THEMES.find(x=>x.id===el.dataset.id);draft.assets=t.assets.map((symbol,i)=>({symbol,weight:String(t.weights[i])}));if(!draft.name)draft.name=t.name+' Set';if(!draft.symbol)draft.symbol=('MY'+t.symbol).slice(0,8);if(!draft.thesis)draft.thesis=t.thesis;save();go('community');return;}if(a==='equal'){syncDraft();const base=Math.floor(10000/draft.assets.length);draft.assets.forEach((a,i)=>a.weight=String((i===draft.assets.length-1?10000-base*(draft.assets.length-1):base)/100));save();render();return;}if(a==='add'){syncDraft();const next=state.assets.find(a=>!draft.assets.some(x=>x.symbol===a.tokenSymbol));if(next&&draft.assets.length<12)draft.assets.push({symbol:next.tokenSymbol,weight:'0'});save();render();return;}if(a==='remove'){syncDraft();if(draft.assets.length>2)draft.assets.splice(+el.dataset.index,1);save();render();return;}if(a==='copy'){await navigator.clipboard.writeText(location.origin+'/#basket/'+el.dataset.address);notify('Real vault link copied.');return;}if(a==='operation'){state.operation=el.dataset.op;state.shares='1';for(const v of Object.values(state.vaults))v.orderAmounts=null;render();return;}if(a==='preview-operation'){await previewOperation(el.dataset.vault);return;}if(a==='approve-vault'){await approveToken(el.dataset.symbol,el.dataset.vault,el.dataset.amount);return;}if(a==='review-vault-op'){await reviewOperation(el.dataset.vault);return;}if(a==='review-claim'){await reviewClaim(el.dataset.vault,el.dataset.exit);return;}if(a==='send'){await send();return;}if(a==='trade-token'){state.swap.symbol=el.dataset.symbol;state.swap.side='buy';state.swap.amount='5';delete state.swap.targetAmount;state.quote=null;go('tokens');return;}if(a==='acquire'){saved.journey={account:state.account,vault:el.dataset.vault,shares:state.shares};save();const price=p(el.dataset.symbol);if(!price?.ok)throw Error('A fresh component mark is required.');const raw=BigInt(el.dataset.amount)*price.ask18/SCALE;const budget=(raw*103n/100n+10n**12n-1n)/10n**12n;state.swap={symbol:el.dataset.symbol,side:'buy',amount:formatUnits(budget,6),targetAmount:el.dataset.amount,slippage:100};state.quote=null;go('tokens');return;}if(a==='swap-side'){state.swap.side=el.dataset.side;state.swap.amount=state.swap.side==='buy'?'5':'0.01';delete state.swap.targetAmount;state.quote=null;render();return;}if(a==='sell-purchase'){const f=saved.lastSwap;if(!f||f.account!==state.account||f.side!=='buy')throw Error('No confirmed purchase for this wallet.');const balance=await token(f.symbol).balanceOf(state.account);if(balance<BigInt(f.buyAmount))throw Error('The purchased quantity is no longer available in your wallet.');state.swap={symbol:f.symbol,side:'sell',amount:formatUnits(f.buyAmount,18),slippage:100};state.quote=null;render();return;}if(a==='get-quote'){await getQuote();return;}if(a==='approve-swap'){const q=validQuote();await approveToken(state.swap.side==='buy'?'USDG':state.swap.symbol,q.approvalSpender,q.spendingCap);return;}if(a==='review-swap'){await reviewSwap();return;}}catch(err){inputError(err);const send=$('button[data-action="send"]');if(send&&!state.busy){send.disabled=!!state.review?.sentHash;send.textContent=state.review?.sentHash?'SUBMITTED / CHECK EXPLORER':'CONTINUE IN WALLET';}}});
