document.addEventListener('change',e=>{const t=e.target;if(t.id==='exit-slippage'){liquidation.input(t);return;}if(t.id==='fund-slippage'){funding.input(t);return;}if(t.id==='radar-sort'){state.radarDirection=t.value==='asc'?'asc':'desc';radarPreferences();render();return;}if(t.id==='catalogue-sort'){state.sort=t.value;saved.preferences={...saved.preferences,sort:state.sort};save();render();return;}if(t.id==='token-filter'){state.tokenFilter=t.value;render();return;}if(t.dataset.token!==undefined){draft.assets[+t.dataset.token].symbol=t.value;save();$('#live-preview').innerHTML=draftPreview();}if(t.id==='swap-symbol'){state.swap.symbol=t.value;delete state.swap.targetAmount;state.quote=null;render();}if(t.id==='swap-slippage'){state.swap.slippage=Number(t.value);state.quote=null;render();}});
document.addEventListener('keydown',e=>{const typing=e.target.closest('input,textarea,select,[contenteditable="true"]');if(!state.busy&&((e.key==='/'&&!typing)||((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'))){e.preventDefault();openSearch();return;}if(e.key==='Escape'){if(state.nav){state.nav=false;render();}close();}if(e.key==='Tab'&&$('#overlay .modal')){const list=[...$('#overlay').querySelectorAll('button:not(:disabled),a[href],input,select,textarea')];if(!list.length)return;const first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
