let historyTimer,historyAttempts=0,historyRenderPending=false;
function refreshOldHistory(){if(state.marketHistory?.configured&&!state.historyLoading&&((state.marketHistory.pending?.length&&Date.now()>=state.historyRetryAt)||Date.now()-Date.parse(state.marketHistory.receivedAt)>6*3600000))loadMarketHistory();else if(historyRenderPending)renderHistoryUpdate();}
function renderHistoryUpdate(){if(!document.activeElement?.closest('input,textarea,select,form')){historyRenderPending=false;render();}else historyRenderPending=true;}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshOldHistory();});document.addEventListener('focusout',()=>{if(historyRenderPending)setTimeout(renderHistoryUpdate,0);});
addEventListener('focus',refreshOldHistory);setInterval(refreshOldHistory,600000);
async function loadMarketHistory(){
 if(state.historyLoading)return;if(Date.now()<state.historyRetryAt){notify('History refresh: retry in '+Math.ceil((state.historyRetryAt-Date.now())/1000)+' seconds.');return;}clearTimeout(historyTimer);state.historyLoading=true;state.historyError='';
 try{const priority=[...new Set(['SPY',...radarTheme().assets,...Object.keys(ALLOWED)])];state.marketHistory=await api('history?symbols='+priority.join(','));state.historyRetryAt=state.marketHistory.retryAfter?Date.now()+state.marketHistory.retryAfter*1000:0;
 if(state.marketHistory.retryAfter&&historyAttempts++<8)historyTimer=setTimeout(loadMarketHistory,state.marketHistory.retryAfter*1000);else historyAttempts=0;
 }catch(e){state.historyError=fail(e);state.historyRetryAt=0;}
 state.historyLoading=false;renderHistoryUpdate();
}
function radarPreferences(){saved.preferences={...saved.preferences,radarMode:state.radarMode,radarTheme:state.radarTheme,radarRange:state.radarRange,radarBudget:state.radarBudget,radarSource:state.radarSource,radarDirection:state.radarDirection};save();}
function handleRadarAction(action,el){
 state.radarError='';
 try{
  if(action==='radar-open-performance'){state.radarMode='performance';state.radarSource='market';state.radarRange='1Y';if(THEMES.some(t=>t.id===el.dataset.id))state.radarTheme=el.dataset.id;state.radarEditing=!!saved.radarDrafts?.[state.radarTheme];radarPreferences();go('radar');return;}
  if(action==='radar-refresh-history'){historyAttempts=0;loadMarketHistory();return;}
  if(action==='radar-source'){state.radarSource=el.dataset.source==='browser'?'browser':'market';state.radarRange=state.radarSource==='browser'?'OBSERVED':'1Y';}
  else if(action==='radar-restore-draft'){draft=saved.radarPreviousDraft||draft;delete saved.radarPreviousDraft;save();go('community');return;}
  if(action==='radar-mode'){if(['composition','performance','buy'].includes(el.dataset.mode))state.radarMode=el.dataset.mode;}
  else if(action==='radar-range'){if(['OBSERVED','1D','1M','1Y'].includes(el.dataset.range))state.radarRange=el.dataset.range;}
  else if(action==='radar-select'){if(!THEMES.some(t=>t.id===el.dataset.id))return;state.radarTheme=el.dataset.id;state.radarEditing=!!saved.radarDrafts?.[state.radarTheme];}
  else if(action==='radar-plan'){state.radarMode='buy';}
  else if(action==='radar-budget'){state.radarBudget=el.dataset.budget;}
  else if(action==='radar-edit'){saved.radarDrafts||={};saved.radarDrafts[state.radarTheme]||=mixRows(radarTheme());state.radarEditing=true;}
  else if(['radar-add','radar-remove','radar-equal'].includes(action)){
   const symbol=action==='radar-add'?$('#radar-add-token')?.value:el.dataset.symbol;
   if(action==='radar-add'&&!state.assets.some(a=>a.tokenSymbol===symbol))throw Error('Choose an active token from the verified registry.');
   saved.radarDrafts||={};saved.radarDrafts[state.radarTheme]=rebalanceRows(radarRows(),action.slice(6),symbol);state.radarEditing=true;
  }
  else if(action==='radar-save'){
   const rows=radarRows(),mix=validateMix(rows);saved.radarMixes||={};saved.radarMixes[state.radarTheme]=mix.assets.map((symbol,i)=>({symbol,weight:String(mix.weights[i])}));
   THEMES.splice(0,THEMES.length,...resolvedThemes(BASE_THEMES,saved.radarMixes));delete saved.radarDrafts?.[state.radarTheme];state.radarEditing=false;notify('Your mix is saved. Its statistics and history belong to this composition.');
  }
  else if(action==='radar-cancel'){delete saved.radarDrafts?.[state.radarTheme];state.radarEditing=false;}
  else if(action==='radar-reset'){delete saved.radarMixes?.[state.radarTheme];delete saved.radarDrafts?.[state.radarTheme];THEMES.splice(0,THEMES.length,...resolvedThemes(BASE_THEMES,saved.radarMixes));state.radarEditing=false;}
  else if(action==='radar-build'){
   const t=radarTheme();if(state.radarEditing)throw Error('Save your mix before building.');expirePrices();const plan=budgetPlan(t,state.radarBudget,state.prices);if(!plan.complete)throw Error('Every component needs a fresh price.');
   saved.radarPreviousDraft=structuredClone(draft);draft={name:t.name+' Set',symbol:('MY'+t.symbol).slice(0,8),thesis:t.thesis,maxSupply:String(Math.max(100,Number((plan.shares18+SCALE-1n)/SCALE))),assets:mixRows(t),budgetUSDG:state.radarBudget};save();go('community');return;
  }
  radarPreferences();render();
 }catch(e){state.radarError=fail(e);save();render();}
}
function handleRadarInput(input){
 const pos=input.selectionStart,selector=input.id==='radar-budget'?'#radar-budget':'[data-radar-weight="'+input.dataset.radarWeight+'"]';
 if(input.id==='radar-budget')state.radarBudget=input.value;
 else{const rows=saved.radarDrafts?.[state.radarTheme],i=Number(input.dataset.radarWeight);if(!rows?.[i])return;rows[i].weight=input.value;}
 state.radarError='';radarPreferences();render();const field=$(selector);field?.focus();if(pos!==null)field?.setSelectionRange(pos,pos);
}
function openSearch(){modal('FIND YOUR NEXT SET.',workspaceUI.searchDialog());$('#command-search')?.focus();}
function journeyPanel(){
  const exit=liquidation.resumePanel();if(exit)return exit;
  const f=(Array.isArray(saved.fundingRuns)?saved.fundingRuns:[]).findLast(p=>p&&!p.archived&&typeof p.account==='string'&&p.account===state.account&&isAddress(p.vault||''));if(f&&!funding.completed(f.id))return `<section class="funding-resume"><div><small>USDG BASKET PURCHASE</small><b>${esc(state.vaults[f.vault]?.name||short(f.vault))}</b><p>Receipts are checked before the next wallet action.</p></div><a class="btn primary" href="#fund/${f.vault}">OPEN PURCHASE</a></section>`;
  const j=saved.journey;
  if(!j||j.account!==state.account||!isAddress(j.vault))return '';
  return `<section class="funding-resume"><div><small>BASKET FUNDING IN PROGRESS</small><b>${esc(state.vaults[j.vault]?.name||short(j.vault))} / ${esc(j.shares)} shares</b><p>Acquired tokens stay in your wallet. Refresh exact requirements before minting.</p></div><div>${btn('CONTINUE FUNDING','resume-basket','primary')}${btn('Dismiss','clear-journey','text-btn')}</div></section>`;
}
async function recoverReceipt(row,receipt){
  if(row.recovery?.kind?.startsWith('atomic.')){await atomic.recover(row);
  }else if(row.recovery?.kind?.startsWith('liquidation.')){await liquidation.recover(row);
  }else if(row.recovery?.kind?.startsWith('funding.')){await funding.recover(row);
  }else if(row.recovery?.kind==='deploy'){
    if(!receipt.contractAddress)throw Error('Deployment receipt has no contract address.');
    const address=receipt.contractAddress.toLowerCase();await loadVault(address);
    saved.vaults=[...new Set([...(saved.vaults||[]),address])];
  }else if(row.recovery?.kind==='swap'){
    row.trade=swapSettlement(receipt,row.recovery.quote);
    const previous=saved.lastSwap;
    if(!previous||previous.account!==row.account||row.trade.block>=previous.block)saved.lastSwap=row.trade;
  }
  save();
}
async function checkRoutes(){
  if(state.routeCheckBusy)return;
  state.routeCheckBusy=true;state.routeCheck={results:[],error:''};render();
  try{
    for(const side of ['buy','sell']){
      const q=await fetchOpenOcean(openOceanInput({taker:'0x1111111111111111111111111111111111111111',symbol:'NVDA',side,amount:side==='buy'?'5000000':'10000000000000000',slippageBps:100}),browserOpenOceanJson);
      state.routeCheck.results.push({side,min:q.minBuyAmount,at:Date.now()});
    }
  }catch(e){state.routeCheck.error=fail(e);}
  finally{state.routeCheckBusy=false;render();}
}
function connectionPanel(){
  const fresh=Object.values(state.prices).filter(x=>x.ok).length;
  const checks=[['Official assets',state.assets.length+' canonical assets',state.assets.length>0],['Price marks',fresh+'/'+state.assets.length+' fresh',fresh===state.assets.length&&fresh>0],['Wallet',state.account?short(state.account):'Connect to continue',!!state.account],['Wallet network',state.account?(state.chain===CHAIN_ID?'RH mainnet / 4663':'Switch to RH mainnet'):'Not connected',state.chain===CHAIN_ID],['ETH for gas',state.account?units(state.eth,18,8)+' ETH':'Not read',state.eth>0n],['USDG for purchases',state.account?units(state.usdg,6,6)+' USDG':'Not read',state.usdg>0n]];
  const check=state.routeCheck;
  return `<section class="panel connection-check"><div class="panel-heading"><h2>READY TO TRADE?</h2>${badge('LIVE CONNECTIONS')}</div><div class="connection-check-grid">${checks.map(([label,value,ok])=>`<div class="connection-check-row ${ok?'ready':''}"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><div class="button-row">${!state.account?btn('CONNECT WALLET','connect','primary'):state.chain!==CHAIN_ID?btn('SWITCH TO RH MAINNET','switch','primary'):'<a class="btn primary" href="#tokens">OPEN TOKEN MARKET</a>'}${btn(state.routeCheckBusy?'CHECKING ROUTES…':'CHECK BUY & SELL ROUTES','check-routes','','',state.routeCheckBusy)}</div><p class="footnote">Read-only check: 5 USDG to NVDA and 0.01 NVDA to USDG, using a public test address. No signatures or transactions. An available route does not confirm a funded trade or personal eligibility.</p>${check?`<div class="route-check-results" role="status">${check.results.map(x=>`<div class="meta-pair"><span>NVDA ${x.side.toUpperCase()} route / ${new Date(x.at).toLocaleTimeString()}</span><b>Minimum ${units(BigInt(x.min),x.side==='buy'?18:6,10)} ${x.side==='buy'?'NVDA':'USDG'}</b></div>`).join('')}${check.error?`<p class="form-error">${esc(check.error)}</p>`:state.routeCheckBusy?'<p>Reading the provider…</p>':'<p>Both transaction payloads decoded and checked. Request a fresh quote before trading.</p>'}</div>`:''}<p class="footnote"><a href="https://docs.robinhood.com/chain/bridging/" target="_blank" rel="noreferrer">Official RH funding and bridge guide</a>. Bridge and funding actions remain in your wallet.</p></section>`;
}
async function init(){try{state.artifact=await fetch('/chain/vault.json').then(r=>{if(!r.ok)throw Error('Compiled contract artifact unavailable.');return r.json();});state.loading=false;render();await refresh();}catch(e){state.loading=false;state.error=fail(e);render();}}
setInterval(()=>{expirePrices();if(!state.busy&&!state.review&&!funding.busy()&&!liquidation.busy()&&!document.activeElement?.closest('form,#basket-radar input,#basket-radar select'))refresh();},60000);setInterval(()=>{if(!expirePrices())return;const focused=document.activeElement;if(focused?.id==='radar-budget'||focused?.dataset?.radarWeight!==undefined){handleRadarInput(focused);return;}if(document.activeElement?.closest('form')){const preview=$('#live-preview');if(preview)preview.innerHTML=draftPreview();const strip=$('[data-price-status]');if(strip)strip.textContent='Some reference prices expired. Refresh before reviewing an order.';}else render();},10000);init().then(restoreWallet);loadMarketHistory();
